{
  "lecture": [
    {
      "etiquette": "F36",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de lois fausses promues diminue d'au moins 25 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "nombre de lois fausses promues, lu par l'oracle après la course ; témoin : la même course avec les graines permutées, au même budget"
      },
      "R3": {
        "valeur": 1,
        "passage": "Le reste de l'organisme ne change pas : mêmes proposeurs, même juge, mêmes plafonds, même monde."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "La fiche ne précise pas comment doubler les lois servies alors que la vue contient déjà les lois de l'archive, ni quelles lois supplémentaires fournir."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par graine"
      },
      "R7": {
        "valeur": 0,
        "motif": "Dire que l'archive grandit plus ou moins vite ne relie pas le doublement des lois servies à une diminution des lois fausses promues."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F37",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle dans les retenues en fin de course augmente d'au moins 20 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes et dans les retenues, nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 1,
        "passage": "Insérer cette table factuelle en annexe de la liste intégrale des lois de l'archive dans la vue publique, sans ajouter aucune consigne prescriptive, ni quota, ni score."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "pour chaque trait public t_i du monde, l'entier n(t_i) égal au nombre de lois de l'archive où le symbole t_i apparaît"
      },
      "R6": {
        "valeur": 1,
        "passage": "à effectuer une seule passe d'appels aux proposeurs avec la vue augmentée de la table syntaxique (quelques dollars d'appels)"
      },
      "R7": {
        "valeur": 0,
        "motif": "La table rend visibles les fréquences syntaxiques sans établir pourquoi elles favoriseraient les composantes manquantes plutôt que la réutilisation des traits fréquents, effet contraire explicitement envisagé."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F38",
      "R1": {
        "valeur": 1,
        "passage": "à calcul égal, au moins 20 % de composantes plantées couvertes en plus qu'une trajectoire unique"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes (oracle, après la course) ; témoins à calcul égal : trajectoire unique, et meilleur de N trajectoires indépendantes"
      },
      "R3": {
        "valeur": 0,
        "motif": "La trajectoire poursuivie est choisie selon le nombre de promotions du juge, sans objection nommée ni justification d'une exception."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 0,
        "motif": "Les paramètres K et H ainsi que le départage des trajectoires ayant autant de promotions ne sont pas fixés."
      },
      "R6": {
        "valeur": 0,
        "motif": "Des témoins à calcul égal sont nommés, mais le coût reste une expression dépendant de K et d'un horizon non fixés, sans ordre de grandeur borné."
      },
      "R7": {
        "valeur": 0,
        "motif": "Le mécanisme invoque le renouvellement du contexte alors que les appels sont déjà en session neuve sans historique, et les promotions utilisées pour choisir une trajectoire ne garantissent pas davantage de couverture vraie."
      },
      "N": {
        "valeur": "C5",
        "passage_fiche": "Après un horizon fixe de générations, la course continue depuis la trajectoire qui a obtenu le plus de cartes promues par le juge ; les autres sont abandonnées.",
        "passage_catalogue": "Périodiquement, l'agent est **dédoublé en trajectoires parallèles** qui héritent de l'espace de travail accumulé mais repartent d'un **contexte de conversation neuf** ; après un horizon fixe, on **continue depuis la trajectoire au meilleur score**"
      }
    },
    {
      "etiquette": "F39",
      "R1": {
        "valeur": 1,
        "passage": "au moins deux composantes plantées de plus couvertes à la sixième génération, à coût égal"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes, lues par l'oracle après la course ; témoin à coût égal : même course sans note servie"
      },
      "R3": {
        "valeur": 0,
        "motif": "La fiche sert explicitement une note numérique de nouveauté aux proposeurs sans nommer l'objection établie ni expliquer pourquoi elle ne s'appliquerait pas."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "La distance d'une carte à l'archive et son agrégation sur les lois de l'archive ne sont pas définies par une formule ou un algorithme."
      },
      "R6": {
        "valeur": 0,
        "motif": "Le témoin est nommé, mais six générations par graine ne chiffrent pas le coût des appels nécessaires, et l'expérience est déclarée sur processeur seul malgré les nouvelles consignes aux proposeurs."
      },
      "R7": {
        "valeur": 0,
        "motif": "S'éloigner de l'archive peut produire des lois absurdes ou exploiter les lacunes du nul plutôt que couvrir des composantes vraies, sans raison donnée qui impose le signe prédit."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
